/**
 * Scoopr service worker (Phase 5, Prompt 2).
 *
 * Hand-written rather than generated by a build plugin — see the "Why a
 * hand-written service worker" section of the README for the reasoning.
 * Deliberately minimal: its only job is to make the app installable and
 * make repeat loads of the app *shell* (HTML/CSS/JS/icons) fast. It must
 * NEVER cache API responses — Scoopr is a live content app, and cards /
 * tips / facts should always come from the network.
 *
 * Bump CACHE_NAME whenever this file's caching logic changes so old
 * caches get cleaned up on the next activate.
 */

const CACHE_NAME = 'scoopr-shell-v1';

self.addEventListener('install', () => {
  // Activate this version as soon as it's done installing, rather than
  // waiting for all tabs of the old version to close. Fine for a personal
  // app where "always run the latest shell" matters more than avoiding a
  // mid-session swap.
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)))
      )
      .then(() => self.clients.claim())
  );
});

function isApiPath(url) {
  // Covers both a same-origin /api/ path (if Scoopr is ever deployed
  // behind a single reverse-proxied origin) and defends in depth even
  // though cross-origin API calls (the default setup — see
  // VITE_API_BASE_URL) never reach this branch, because of the
  // cross-origin check below.
  return url.pathname.startsWith('/api/');
}

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only ever handle simple GETs. POST/PUT/PATCH/DELETE (logins, card
  // actions, admin actions, etc.) must always go straight to the network
  // untouched.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);

  // Anything cross-origin (the backend API, Google Fonts, etc.) or any
  // same-origin /api/ call is explicitly left alone — no respondWith,
  // no caching, just the normal network request. This is what keeps
  // cards / tips / facts / auth state always fresh.
  if (url.origin !== self.location.origin || isApiPath(url)) {
    return;
  }

  // Page navigations (loading or refreshing a route): network-first, so
  // a user online always gets the current shell, with a cached fallback
  // for offline/flaky-connection loads.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
          return response;
        })
        .catch(
          () =>
            caches.match(request).then((cached) => cached) ||
            caches.match('/index.html')
        )
    );
    return;
  }

  // Static app-shell assets (hashed JS/CSS bundles, icons, fonts):
  // stale-while-revalidate. Serve the cached copy instantly when present
  // for fast repeat loads, while always firing a network request in the
  // background to refresh the cache for next time.
  event.respondWith(
    caches.match(request).then((cached) => {
      const networkFetch = fetch(request)
        .then((response) => {
          if (response && response.ok) {
            const copy = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, copy));
          }
          return response;
        })
        .catch(() => cached);
      return cached || networkFetch;
    })
  );
});
